/**
 * Produce a non-recursive iterator over the instance given its runtime model type.
 */
std::unique_ptr<impl::IIterator> NewNonRecursiveIterator(
  const std::shared_ptr<types::IClass>& instance
) {
  switch (instance->model_type()) {
    case types::ModelType::kStructuralFirst:
      return common::make_unique<IteratorOverStructuralFirst>(
        instance
      );
    case types::ModelType::kStructuralSecond:
      return common::make_unique<IteratorOverStructuralSecond>(
        instance
      );
    case types::ModelType::kMixedAbstractDescendantOne:
      return common::make_unique<IteratorOverMixedAbstractDescendantOne>(
        instance
      );
    case types::ModelType::kMixedAbstractDescendantTwo:
      return common::make_unique<IteratorOverMixedAbstractDescendantTwo>(
        instance
      );
    case types::ModelType::kMixedConcreteWithDescendants:
      return common::make_unique<IteratorOverMixedConcreteWithDescendants>(
        instance
      );
    case types::ModelType::kMixedConcreteWithDescendantsChild:
      return common::make_unique<IteratorOverMixedConcreteWithDescendantsChild>(
        instance
      );
    case types::ModelType::kMixedConcreteLeaf:
      return common::make_unique<IteratorOverMixedConcreteLeaf>(
        instance
      );
    case types::ModelType::kModelTypedFirst:
      return common::make_unique<IteratorOverModelTypedFirst>(
        instance
      );
    case types::ModelType::kModelTypedSecond:
      return common::make_unique<IteratorOverModelTypedSecond>(
        instance
      );
    case types::ModelType::kSomething:
      return common::make_unique<IteratorOverSomething>(
        instance
      );
    default:
      throw std::logic_error(
        common::Concat(
          "Unexpected model type: ",
          std::to_string(
            static_cast<std::uint32_t>(instance->model_type())
          )
        )
      );
  }
}

